const markGitHooksNotUpdated = `-- name: MarkGitHooksNotUpdated :exec
UPDATE git_repo_map SET hook_state = 'failed', hook_error = 'not_updated'
WHERE org_id = $1 AND integration_id = $2
`

type MarkGitHooksNotUpdatedParams struct {
	OrgID         uuid.UUID
	IntegrationID uuid.UUID
}

// Token-mode rotation (T17 #11): a NEW pending secret means no hook holds it
// yet, so every mapped repo is "not updated" until a push succeeds. A retry
// reuses the pending secret and pushes only to the repos that are not active.
// scope: admin
func (q *Queries) MarkGitHooksNotUpdated(ctx context.Context, arg MarkGitHooksNotUpdatedParams) error {
	_, err := q.db.Exec(ctx, markGitHooksNotUpdated, arg.OrgID, arg.IntegrationID)
	return err
}

const restrictedAccessExists = `-- name: RestrictedAccessExists :one
SELECT (EXISTS (SELECT 1 FROM org_members m WHERE m.org_id = $1::uuid AND m.team_access = 'selected')
     OR EXISTS (SELECT 1 FROM org_invites i
                WHERE i.org_id = $1::uuid AND i.team_access = 'selected'
                  AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()))::boolean AS restricted
`

// scope: admin
// A member with team_access 'selected', whatever the role (fail closed), or
// an open invite that would make one (not accepted, not revoked, not expired;
// an expired invite can never be used, ConsumeOrgInvite).
func (q *Queries) RestrictedAccessExists(ctx context.Context, orgID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, restrictedAccessExists, orgID)
	var restricted bool
	err := row.Scan(&restricted)
	return restricted, err
}

